// In-memory token session database (avoiding iframe cookie блокировки)
const activeSessions: Record<string, any> = {};

// Authorization Checker helper
function getMe(req: express.Request) {
  const authHeader = req.headers["authorization"] || req.headers["x-session-id"];
  if (!authHeader) return null;
  const token = String(authHeader).replace("Bearer ", "");
  return activeSessions[token] || null;
}

