// PHP DB endpoints mimic
// 1. LOGIN
app.post("/api/auth/login.php", (req, res) => {
  const { email, password } = req.body;
  const db = getDB();
  const user = db.users.find((u: any) => u.email === email);

  if (!user) {
    return res.status(401).json({ ok: false, error: "Invalid email or password" });
  }

  // Support both password_hash strings or simulated strings
  if (password !== "admin123" && password !== "user123" && password !== user.password_hash) {
    return res.status(401).json({ ok: false, error: "Invalid email or password" });
  }

  // Generate fake token/session key
  const token = `session_${user.id}_${Date.now()}`;
  activeSessions[token] = {
    id: user.id,
    email: user.email,
    name: user.name,
    role: user.role
  };

  res.json({
    ok: true,
    token, // Return token to store client-side inside simulator LocalStorage
    user: {
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role
    }
  });
});

// 2. REGISTER
app.post("/api/auth/register.php", (req, res) => {
  const { name, email, password } = req.body;
  if (!name || !email || !password) {
    return res.status(400).json({ ok: false, error: "All fields are required" });
  }

  const db = getDB();
  if (db.users.some((u: any) => u.email === email)) {
    return res.status(400).json({ ok: false, error: "Email is already registered" });
  }

  const newUser = {
    id: db.users.length + 1,
    email,
    password_hash: password, // simple simulated save
    name,
    role: db.users.length === 0 ? "admin" : "user",
    created_at: new Date().toISOString().replace("T", " ").substring(0, 19)
  };

  db.users.push(newUser);
  saveDB(db);

  res.json({ ok: true });
});

// 3. LOGOUT
app.post("/api/auth/logout.php", (req, res) => {
  const authHeader = req.headers["authorization"] || req.headers["x-session-id"];
  if (authHeader) {
    const token = String(authHeader).replace("Bearer ", "");
    delete activeSessions[token];
  }
  res.json({ ok: true });
});

